resources.Resource:
JdbcDriver = org.postgresql.Driver
JdbcUrl = ${POSTGRES_URL:-jdbc:postgresql://localhost:5432/stock_market}
UserName = ${POSTGRES_USER:-stock_app}
Password = ${POSTGRES_PASSWORD}
JtaManaged = true

JdbcDriver = com.microsoft.sqlserver.jdbc.SQLServerDriver
JdbcUrl = ${SQLSERVER_URL:-jdbc:sqlserver://localhost:1433;databaseName=stock_market;encrypt=false}
UserName = ${SQLSERVER_USER:-stock_app}
Password = ${SQLSERVER_PASSWORD}
JtaManaged = true

JdbcDriver = oracle.jdbc.OracleDriver
JdbcUrl = ${ORACLE_URL:-jdbc:oracle:thin:@localhost:1521/FREEPDB1}
UserName = ${ORACLE_APP_USER:-${ORACLE_USER:-stock_app}}
Password = ${ORACLE_APP_PASSWORD}
JtaManaged = true
